SET NAMES utf8;

UPDATE `script_texts` SET `content_loc4` = '这边走，我们的房子在那里，穿过灌木丛就到。' WHERE `entry` = -1000111 AND BINARY `content_default` = 'Our house is this way, through the thicket.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我可怜的家人……一切都被毁了。' WHERE `entry` = -1000113 AND BINARY `content_default` = 'My poor family. Everything has been destroyed.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '爸爸！爸爸！你还活着！' WHERE `entry` = -1000114 AND BINARY `content_default` = 'Father! Father! You''re alive!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s拥抱着她的父亲。' WHERE `entry` = -1000116 AND BINARY `content_default` = '%s hugs her father.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '看！他们在跟踪我们！' WHERE `entry` = -1000118 AND BINARY `content_default` = 'Over there! They''re following us!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '请让我休息一会，我已经非常累了。' WHERE `entry` = -1000119 AND BINARY `content_default` = 'Allow me a moment to rest. The journey taxes what little strength I have.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '终于到了猎鹰岗哨！现在，我的……？天哪！我的背包找不到了！这可怎么办……' WHERE `entry` = -1000121 AND BINARY `content_default` = 'Falcon Watch, at last! Now, where''s my... Oh no! My pack, it''s missing! Where has -' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你休想阻止我到达猎鹰岗哨！' WHERE `entry` = -1000122 AND BINARY `content_default` = 'You won''t keep me from getting to Falcon Watch!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '阿尔杜尼斯，我们要你派增援去法力熔炉：杜隆。这不是请求，而是命令。' WHERE `entry` = -1000128 AND BINARY `content_default` = 'We need you to send reinforcements to Manaforge Duro, Ardonis. This is not a request, it''s an order.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你不会是认真的吧！我们的人手已经严重不足，都快要不能维持法力熔炉的正常运作了！' WHERE `entry` = -1000129 AND BINARY `content_default` = 'You cannot be serious! We are severely understaffed and can barely keep this manaforge functional!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '照命令行事。法力熔炉：杜隆正遭到魔法生物的猛烈攻击，局势已经失控。任何违抗命令的行为都绝不容忍！' WHERE `entry` = -1000130 AND BINARY `content_default` = 'You will do as ordered. Manaforge Duro has come under heavy attack by mana creatures and the situation is out of control. Failure to comply will not be tolerated!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '没错，这不是请求。' WHERE `entry` = -1000131 AND BINARY `content_default` = 'Indeed, it is not a request.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '大人！' WHERE `entry` = -1000132 AND BINARY `content_default` = 'My lord!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '杜隆必须得到增援！乌提斯完全是个灾难。我不允许这种错误重演！' WHERE `entry` = -1000133 AND BINARY `content_default` = 'Duro will be reinforced! Ultris was a complete disaster. I will NOT have that mistake repeated!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '一路上我们受到了太多的挫折：地狱火堡垒、坠星山、火翼岗哨……凯尔萨斯王子不能再容忍任何延误了。除了成功，我什么都不想看到。' WHERE `entry` = -1000134 AND BINARY `content_default` = 'We''ve had too many setbacks along the way: Hellfire Citadel, Fallen Sky Ridge, Firewing Point... Prince Kael''thas will tolerate no further delays. I will tolerate nothing other than complete success!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我要返回风暴要塞了。你们最好不要让我有回来的理由！' WHERE `entry` = -1000135 AND BINARY `content_default` = 'I am returning to Tempest Keep. See to it that I do not have reason to return!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你给我确保一切正常，阿尔杜尼斯！' WHERE `entry` = -1000137 AND BINARY `content_default` = 'See to it, Ardonis!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '亚维鲁的魔法……仍然控制着我。你必须与我战斗，凡人。这是唯一可以解除那个魔法的办法！' WHERE `entry` = -1000138 AND BINARY `content_default` = 'Avruu''s magic... it still controls me. You must fight me, mortal. It''s the only way to break the spell!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '亚维鲁的魔法失效了！我又自由了！' WHERE `entry` = -1000139 AND BINARY `content_default` = 'Avruu''s magic is broken! I''m free once again!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我能看到通道那头的亮光了！' WHERE `entry` = -1000142 AND BINARY `content_default` = 'I can see the light at the end of the tunnel!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '赫里奥斯中尉，我从阿曼尼墓穴逃出来了。报告，长官！' WHERE `entry` = -1000145 AND BINARY `content_default` = 'Captain Helios, I''ve been rescued from the Amani Catacombs. Reporting for duty, sir!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我仍然清晰地记得上次战争败北的耻辱。我等待复仇的机会已经等得太久了。现在，军团的阴影将笼罩这个世界，你们彻底毁灭的日子……已经不远了。' WHERE `entry` = -1000147 AND BINARY `content_default` = 'I remember well the sting of defeat at the conclusion of the Third War. I have waited far too long for my revenge. Now the shadow of the Legion falls over this world. It is only a matter of time until all of your failed creation... is undone.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '军团将会征服一切！' WHERE `entry` = -1000148 AND BINARY `content_default` = 'The Legion will conquer all!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '所有的凡人都将灭亡!' WHERE `entry` = -1000149 AND BINARY `content_default` = 'All mortals will perish!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '所有的生命都将被根除！' WHERE `entry` = -1000150 AND BINARY `content_default` = 'All life must be eradicated!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我要把你们生吞活剥!' WHERE `entry` = -1000151 AND BINARY `content_default` = 'I''ll rip the flesh from your bones!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '可笑的蠢货！' WHERE `entry` = -1000153 AND BINARY `content_default` = 'Contemptible wretch!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '宇宙将获得新生。' WHERE `entry` = -1000154 AND BINARY `content_default` = 'The universe will be remade.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '军团……永远不会……失败。' WHERE `entry` = -1000155 AND BINARY `content_default` = 'The Legion... will never... fall.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '入侵者，你们在遗忘的深渊边缘摇摆！燃烧军团就是你们的末日！' WHERE `entry` = -1000157 AND BINARY `content_default` = 'Invaders, you dangle upon the precipice of oblivion! The Burning Legion comes and with it comes your end.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '可笑的凡人，你们只是延迟了不可避免的命运。一个恶魔倒下去，十个恶魔会站起来。这就是卡扎克的意志……' WHERE `entry` = -1000158 AND BINARY `content_default` = 'Impudent whelps, you only delay the inevitable. Where one has fallen, ten shall rise. Such is the will of Kazzak...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '哈哈哈哈哈！你这个蠢货！你把我从时空之间的缝隙中放了出来，终结了我的流放！' WHERE `entry` = -1000169 AND BINARY `content_default` = 'Muahahahaha! You fool! You''ve released me from my banishment in the interstices between space and time!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我要从哪里开始？我不能为你这种蠕虫操心。我要征服世界！' WHERE `entry` = -1000171 AND BINARY `content_default` = 'Where shall I begin? I cannot bother myself with a worm such as yourself. There is a world to be conquered!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '不！……' WHERE `entry` = -1000173 AND BINARY `content_default` = 'NOOOOooooooo!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '谢谢你，凡人。' WHERE `entry` = -1000175 AND BINARY `content_default` = 'Thank you, mortal.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我所能记得的最后一件事是飞船在下降，而我们都进入了救生舱。我去看看有什么我可以帮忙的。谢谢你！' WHERE `entry` = -1000176 AND BINARY `content_default` = 'The last thing I remember is the ship falling and us getting into the pods. I''ll go see how I can help. Thank you!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '啊……这里是哪？飞船就只剩下这点了？' WHERE `entry` = -1000179 AND BINARY `content_default` = 'Ugh... what is this place? Is that all that''s left of the ship over there?' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '啊……好疼啊……' WHERE `entry` = -1000180 AND BINARY `content_default` = 'Oh, the pain...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '疼死我了。请想想办法……' WHERE `entry` = -1000181 AND BINARY `content_default` = 'Everything hurts, Please make it stop...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '啊啊啊……疼死我了。你可以帮帮我吗？' WHERE `entry` = -1000182 AND BINARY `content_default` = 'Ughhh... I hurt. Can you help me?' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '是的，主人。一切都在按照计划进行。' WHERE `entry` = -1000184 AND BINARY `content_default` = 'Yes Master, all goes along as planned.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '目标确定。启动安全程序。' WHERE `entry` = -1000189 AND BINARY `content_default` = 'Objective acquired. Initiating security routines.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '在纳格兰，食物竟敢追杀食人魔！' WHERE `entry` = -1000190 AND BINARY `content_default` = 'In Nagrand, food hunt ogre!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '再加点盐和胡椒你就更美味了。' WHERE `entry` = -1000191 AND BINARY `content_default` = 'You taste good with maybe a little salt and pepper.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '好吧，好吧！拉普投降！' WHERE `entry` = -1000192 AND BINARY `content_default` = 'OK, OK! Lump give up!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我投降！不要杀我！' WHERE `entry` = -1000194 AND BINARY `content_default` = 'I give up! Please don''t kill me!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = 'Belore……' WHERE `entry` = -1000196 AND BINARY `content_default` = 'Belore...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s叹了口气，跪下身捡起了护符。' WHERE `entry` = -1000197 AND BINARY `content_default` = 'Sighing, %s kneels down and picks up the amulet.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你要是敢回来，狂心狼獾人就要你的命。从现在开始，你是我们的敌人！' WHERE `entry` = -1000208 AND BINARY `content_default` = 'Frenzyheart kill you if you come back. You no welcome here no more!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '将在一分钟后完成紧急停机。' WHERE `entry` = -1000212 AND BINARY `content_default` = 'Emergency shutdown will complete in one minute.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '将在三十秒后紧急停机。' WHERE `entry` = -1000213 AND BINARY `content_default` = 'Emergency shutdown will complete in thirty seconds.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '将在十秒后紧急停机。' WHERE `entry` = -1000214 AND BINARY `content_default` = 'Emergency shutdown will complete in ten seconds.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '紧急停机已完成。' WHERE `entry` = -1000215 AND BINARY `content_default` = 'Emergency shutdown complete.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '这很奇怪，我知道……大部分凡人无法真正理解他们在这里看到的东西，他们所看到往往无法和他们的理解联系起来。' WHERE `entry` = -1000219 AND BINARY `content_default` = 'It is strange, I know... Most mortals cannot actually comprehend what they see here, as often, what they see is not anchored within their own perception of reality.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '请跟着我。' WHERE `entry` = -1000220 AND BINARY `content_default` = 'Follow me, please.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '在这里只有两条真理：首先，时间是混乱的，永远在不停地变化，并且可以完全改变。第二，感觉并不代表真实。' WHERE `entry` = -1000221 AND BINARY `content_default` = 'There are only two truths to be found here: First, that time is chaotic, always in flux, and completely malleable and second, perception does not dictate reality.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '作为时间的守护者，我们守望并照管着诺兹多姆的领域。主人眼下不在，这意味着有人正试图大幅改变时间。主人从不干涉凡人的事务，只会纠正别人对时间所作的改动。在这方面，他总是采取应对措施。' WHERE `entry` = -1000222 AND BINARY `content_default` = 'As custodians of time, we watch over and care for Nozdormu''s realm. The master is away at the moment, which means that attempts are being made to dramatically alter time. The master never meddles in the affairs of mortals but instead corrects the alterations made to time by others. He is reactionary in this regard.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '对于普通的时间维护工作，时光守护者的力量是足够的。我们可以处理大部分普通的干扰。举个小例子来说，比如某些无赖法师们试图改变过去的一些东西来提升他们现在的身份和财富之类的事情，不在话下。' WHERE `entry` = -1000223 AND BINARY `content_default` = 'For normal maintenance of time, the Keepers of Time are sufficient caretakers. We are able to deal with most ordinary disturbances. I speak of little things, such as rogue mages changing something in the past to elevate their status or wealth in the present.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你看到的这些隧道被称为时间流。它们的数量是无穷的。当前在你们的现实中存在的那个就是主人所认为的“麻烦点”。这些麻烦点也许有着完全不同的内容，但是它们通常都有着相同的原因。它们的存在是同样的时间干扰所产生的结果，当你进入其中的一个麻烦点去冒险时，要牢记这一点……' WHERE `entry` = -1000224 AND BINARY `content_default` = 'These tunnels that you see are called timeways. They are infinite in number. The ones that currently exist in your reality are what the master has deemed as ''trouble spots.'' These trouble spots may differ completely in theme but they always share a cause. That is, their existence is a result of the same temporal disturbance. Remember that should you venture inside one...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '关于这个时间流，我们只得到了很少的一点情报。萨艾特已经被派遣进去了。从和他的通信中，我们获知的情报是永恒之龙再次尝试改变时间。很可能他们的目标是破坏黑暗之门的开启？希望不是这样……' WHERE `entry` = -1000226 AND BINARY `content_default` = 'We have very little information on this timeway. Sa''at has been dispatched and is currently inside. The data we have gathered from his correspondence is that the Infinite Dragonflight are once again attempting to alter time. Could it be that the opening of the Dark Portal is being targeted for sabotage? Let us hope not...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '时间流目前是按照“小灾难”至“大灾难”的顺序排列着的。注意它们全部都是“灾难”，这意味着任何一个时间流的毁灭都会终结你们的世界，没有区别。我们把它们这样分类，只是为了让那些被派到这里来的英雄们和冒险者们知道自己的能力适合处理哪个时间流中的事务。' WHERE `entry` = -1000228 AND BINARY `content_default` = 'The timeways are currently ranked in order from least catastrophic to most catastrophic. Note that they are all classified as catastrophic, meaning that any single one of these timeways collapsing would mean that your world would end. We only classify them in such a way so that the heroes and adventurers that are sent here know which timeway best suits their abilities.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '这个时间流通向海加尔山，我们只知道这些。永恒之龙不顾一切地阻止我们的介入，因此我们对其它的事情丝毫没有头绪，凡人。索莉多米正在尝试着突破时间流的防守，但是迄今都没有成功。你或许是我们突破和解决这个冲突的唯一希望。' WHERE `entry` = -1000229 AND BINARY `content_default` = 'All we know of this timeway is that it leads to Mount Hyjal. The Infinite Dragonflight have gone to great lengths to prevent our involvement. We know next to nothing, mortal. Soridormi is currently attempting to break through the timeway''s defenses but has thus far been unsuccessful. You might be our only hope of breaking through and resolving the conflict.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '跟我来，陌生人。这不会耽误你太长时间的。' WHERE `entry` = -1000234 AND BINARY `content_default` = 'Follow me, stranger. This won''t take long.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '沙塔斯城曾经是德莱尼人在这个世界的首都。它的意思是“圣光的居所”。' WHERE `entry` = -1000235 AND BINARY `content_default` = 'Shattrath was once the draenei capital of this world. Its name means "dwelling of light."' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '当燃烧军团诱使兽人和德莱尼人反目成仇时，激烈的战斗就在这里爆发了。尽管德莱尼人浴血奋战，但最后，城市还是沦陷了。' WHERE `entry` = -1000236 AND BINARY `content_default` = 'When the Burning Legion turned the orcs against the draenei, the fiercest battle was fought here. The draenei fought tooth and nail, but in the end the city fell.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '整座城市只剩下废墟和黑暗……直到沙塔尔来临。' WHERE `entry` = -1000237 AND BINARY `content_default` = 'The city was left in ruins and darkness... until the Sha''tar arrived.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我们去贫民窟走走吧。我要提醒你，作为外域唯一的避风港，沙塔斯城吸引了成群的难民，无论是现在的战争所致，还是以往的战争所致。' WHERE `entry` = -1000238 AND BINARY `content_default` = 'Let us go into the Lower City. I will warn you that as one of the only safe havens in Outland, Shattrath has attracted droves of refugees from all wars, current and past.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '沙塔尔，或者说“生于圣光”，这个词是指来到外域和燃烧军团的恶魔们作战的纳鲁。' WHERE `entry` = -1000239 AND BINARY `content_default` = 'The Sha''tar, or "born from light" are the naaru that came to Outland to fight the demons of the Burning Legion.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '他们被吸引到了沙塔斯城的废墟。在我们脚下这片地方的一座残破神庙中，一小群幸存的德莱尼祭司仍在举行仪式。' WHERE `entry` = -1000240 AND BINARY `content_default` = 'They were drawn to the ruins of Shattrath City where a small remnant of the draenei priesthood conducted its rites inside a ruined temple on this very spot.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '随着纳鲁归来的消息传开，被称为奥尔多的祭司们很快恢复了力量，城市的重建也随即开始。这座残破的神庙如今是救治受伤难民的医务所。' WHERE `entry` = -1000241 AND BINARY `content_default` = 'The priesthood, known as the Aldor, quickly regained its strength as word spread that the naaru had returned and reconstruction soon began. The ruined temple is now used as an infirmary for injured refugees.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '然而好景不长，这座城市再次遭受了攻击。这次，发动进攻的是伊利丹的军队。伊利丹的同盟凯尔萨斯·逐日者派出了一大群血精灵来毁灭这座城市。' WHERE `entry` = -1000242 AND BINARY `content_default` = 'It wouldn''t be long, however, before the city came under attack once again. This time, the attack came from Illidan''s armies. A large regiment of blood elves had been sent by Illidan''s ally, Kael''thas Sunstrider, to lay waste to the city.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '当时一大群血精灵跨过了这座桥，奥尔多的主教和守备官们筑起了人墙，保卫圣光广场。就在这时，意想不到的事情发生了。' WHERE `entry` = -1000243 AND BINARY `content_default` = 'As the regiment of blood elves crossed this very bridge, the Aldor''s exarchs and vindicators lined up to defend the Terrace of Light. But then the unexpected happened.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '血精灵们在城市守卫面前放下了武器。他们的首领，一个被称为沃雷塔尔的血精灵长者，冲进了圣光广场，要求和阿达尔对话。' WHERE `entry` = -1000244 AND BINARY `content_default` = 'The blood elves laid down their weapons in front of the city''s defenders; their leader, a blood elf elder known as Voren''thal, stormed into the Terrace of Light and demanded to speak to A''dal.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '当纳鲁走近他时，沃雷塔尔跪在他的面前，说道：“我在我的梦境里看到过您，纳鲁。您是我的族群唯一的生存希望。我和我的部下愿意为您效劳。”' WHERE `entry` = -1000245 AND BINARY `content_default` = 'As the naaru approached him, Voren''thal kneeled before him and uttered the following words: "I''ve seen you in a vision, naaru. My race''s only hope for survival lies with you. My followers and I are here to serve you."' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '沃雷塔尔和他的追随者们的变节是凯尔萨斯有史以来所遭受到的最严重的损失。他们不是一群普通的血精灵，凯尔萨斯手下很多最睿智、最强大的学者和魔导师也被沃雷塔尔的影响力动摇了。' WHERE `entry` = -1000246 AND BINARY `content_default` = 'The defection of Voren''thal and his followers was the largest loss ever incurred by Kael''s forces. And these weren''t just any blood elves. Many of the best and brightest amongst Kael''s scholars and magisters had been swayed by Voren''thal''s influence.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '奥尔多是圣光的追随者，宽恕和救赎是他们的信条。然而，他们却很难忘记血精灵在凯尔萨斯命令之下的所作所为。' WHERE `entry` = -1000248 AND BINARY `content_default` = 'The Aldor are followers of the Light and forgiveness and redemption are values they understand. However, they found hard to forget the deeds of the blood elves while under Kael''s command.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '许多传教士曾经被那些如今发誓效忠纳鲁的魔导师们杀死。他们对于和旧日的敌人同住在一座城市里面感到非常不悦。' WHERE `entry` = -1000249 AND BINARY `content_default` = 'Many of the priesthood had been slain by the same magisters who now vowed to serve the naaru. They were not happy to share the city with their former enemies.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '奥尔多最神圣的庙宇和它周围的小建筑坐落在上面的广场上。作为一个神圣的场所，只有他们的追随者才被允许进入那里。' WHERE `entry` = -1000250 AND BINARY `content_default` = 'The Aldor''s most holy temple and its surrounding dwellings lie on the terrace above. As a holy site, only the initiated are welcome inside.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '对沙塔斯城的进攻持续着，但是城市并没有沦陷，就像你看到的那样。相反，那个名叫克希利的纳鲁领导了一次成功的反击，一直打到了伊利丹的家门口——影月谷。' WHERE `entry` = -1000251 AND BINARY `content_default` = 'The attacks against Shattrath continued, but the city did not fall, as you can see. On the contrary, the naaru known as Xi''ri led a successful incursion into Shadowmoon Valley - Illidan''s doorstep.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '在奥尔多和占星者的协助下，他不断对伊利丹的军队发动着攻势。然而这两股势力并没有冰释前嫌。' WHERE `entry` = -1000252 AND BINARY `content_default` = 'There he continues to wage war on Illidan with the assistance of the Aldor and the Scryers. The two factions have not given up on their old feuds, though.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '双方的敌意如此之深，连前去协助纳鲁的荣誉都要争个高下。每天由阿达尔在这里决定派遣哪一方。军队会在这里集结，接受阿达尔的祝福，然后开赴影月谷。' WHERE `entry` = -1000253 AND BINARY `content_default` = 'Such is their animosity that they vie for the honor of being sent to assist the naaru there. Each day, that decision is made here by A''dal. The armies gather here to receive A''dal''s blessing before heading to Shadowmoon.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '卡德加应该准备好再次见你了。记住，如果你准备为沙塔尔效力，你很可能不得不与奥尔多或是占星者结盟。同样，对任何一方示好都会引起另外一方的敌意。' WHERE `entry` = -1000254 AND BINARY `content_default` = 'Khadgar should be ready to see you again. Just remember that to serve the Sha''tar you will most likely have to ally with the Aldor or the Scryers. And seeking the favor of one group will cause the others'' dislike.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '祝你好运，陌生人，欢迎来到沙塔斯城。' WHERE `entry` = -1000255 AND BINARY `content_default` = 'Good luck stranger, and welcome to Shattrath City.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '在我数到“3”之前，滚出这里，否则小心我放狗咬你。' WHERE `entry` = -1000275 AND BINARY `content_default` = 'Now I''m gonna give you to the count of ''3'' to get out of here before I sick the dogs on you.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '是时候去见你的造物主了！' WHERE `entry` = -1000278 AND BINARY `content_default` = 'Time to meet your maker!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '好吧，我们投降！不要伤害我们！' WHERE `entry` = -1000279 AND BINARY `content_default` = 'Alright, we give up! Don''t hurt us!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '翡翠梦境永远都不会属于你！' WHERE `entry` = -1000281 AND BINARY `content_default` = 'The Emerald Dream will never be yours!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '滚出这里！' WHERE `entry` = -1000282 AND BINARY `content_default` = 'Begone from this place!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我已经拿到了第二件圣物。休息一会，然后我们继续去最后一个净化之匣那里。' WHERE `entry` = -1000284 AND BINARY `content_default` = 'I''ve recovered the second relic. Take a moment to rest, and then we''ll continue to the last reliquary.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我们已经得到了全部三件圣物，不过我的能量正在迅速消失。我们必须立刻回到梦境卫士鲁罗萨那里去！他会告诉你接下来该怎么做。' WHERE `entry` = -1000285 AND BINARY `content_default` = 'We have all three of the relics, but my energy is rapidly fading. We must make our way back to Dreamwarden Lurosa! He will let you know what to do next.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '咯咯嗒！探测到空间异常——危险临近！咯咯嗒！' WHERE `entry` = -1000290 AND BINARY `content_default` = 'CLUCK! Sensors detect spatial anomaly - danger imminent! CLUCK!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '没人敢挑战废土强盗团——机械小鸡也不行！进攻！' WHERE `entry` = -1000291 AND BINARY `content_default` = 'No one challenges the Wastewander nomads - not even robotic chickens! ATTACK!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '开始试炼吧！布拉维·血怒，给我上！' WHERE `entry` = -1000319 AND BINARY `content_default` = 'Let the trial begin, Bloodwrath, attack!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '勇士莱伦德·光痕，让我为你而骄傲吧！' WHERE `entry` = -1000320 AND BINARY `content_default` = 'Champion Lightrend, make me proud!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '玛尔娅·迅刃，让这个家伙看看真正的血骑士是怎么战斗的！' WHERE `entry` = -1000321 AND BINARY `content_default` = 'Show this upstart how a real Blood Knight fights, Swiftblade!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '斯塔克·射日者，给$n点痛苦尝尝！' WHERE `entry` = -1000322 AND BINARY `content_default` = 'Show $n the meaning of pain, Sunstriker!' AND COALESCE(`content_loc4`, '') = '';
