UPDATE `script_texts` SET `content_loc4` = '%s开心地吃着午餐。' WHERE `entry` = -1000341 AND BINARY `content_default` = '%s eats his lunch.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s跳了一支特殊的舞蹈，对你表示感谢。' WHERE `entry` = -1000342 AND BINARY `content_default` = '%s thanks you with a special dance.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '继续前进吧，这里并不安全！' WHERE `entry` = -1000345 AND BINARY `content_default` = 'Let''s keep moving. We''re not safe here!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我们快到庇护所了！加油。' WHERE `entry` = -1000347 AND BINARY `content_default` = 'We''re almost to the refuge! Let''s go.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '你！快交出月亮石，我保证任何人都不会受到伤害！' WHERE `entry` = -1000351 AND BINARY `content_default` = 'You, there! Hand over that moonstone and nobody gets hurt!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s拿走了南国之怒月亮石，并逃进了河里。跟着她！' WHERE `entry` = -1000352 AND BINARY `content_default` = '%s takes the Southfury moonstone and escapes into the river. Follow her!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '冷静！' WHERE `entry` = -1000353 AND BINARY `content_default` = 'Just chill!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '手榴弹竟然在这种时候逆火，这蠢东西还真会挑时间啊！我受够了这些所谓的高品质地精工程学制品！' WHERE `entry` = -1000354 AND BINARY `content_default` = 'Stupid grenade picked a fine time to backfire! So much for high quality goblin engineering!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '好吧，你赢了！我投降！不要伤害我！' WHERE `entry` = -1000355 AND BINARY `content_default` = 'All right, you win! I surrender! Just don''t hurt me!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '纳迦进攻了！准备战斗！' WHERE `entry` = -1000383 AND BINARY `content_default` = 'Naga attackers! Defend yourself!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '库斯卡的纳迦对他们的战俘异常凶残。我能在水牢里活这么长时间真是个奇迹。感谢大地之母。' WHERE `entry` = -1000385 AND BINARY `content_default` = 'The naga of Coilskar are exceptionally cruel to their prisoners. It is a miracle that I survived inside that watery prison for as long as I did. Earthmother be praised.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '现在我们必须找到出口。' WHERE `entry` = -1000386 AND BINARY `content_default` = 'Now we must find the exit.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '瓦丝琪女王必须为这些暴行负责。她必将得到制裁！' WHERE `entry` = -1000387 AND BINARY `content_default` = 'Lady Vashj must answer for these atrocities. She must be brought to justice!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '艾泽拉斯和德拉诺的大江大河之所以如此狂暴，正是水之灵饱受折磨的结果。' WHERE `entry` = -1000388 AND BINARY `content_default` = 'The tumultuous nature of the great waterways of Azeroth and Draenor are a direct result of tormented water spirits.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '应该不会太远了，$n。出口就在前面。' WHERE `entry` = -1000389 AND BINARY `content_default` = 'It shouldn''t be much further, $n. The exit is just up ahead.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '谢谢你，$n。请回去转告我的兄弟，告诉他们维尔达安全了，他们在古尔丹之手附近的诅咒祭坛那里。愿大地之母保佑你……' WHERE `entry` = -1000390 AND BINARY `content_default` = 'Thank you, $n. Please return to my brethren at the Altar of Damnation, near the Hand of Gul''dan, and tell them that Wilda is safe. May the Earthmother watch over you...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '林吉现在可以告诉你我的秘密了……$n应该去望海崖。林吉在那里的小岛上藏了一点东西。' WHERE `entry` = -1000408 AND BINARY `content_default` = 'Rin''ji will tell you secret now... $n, should go to the Overlook Cliffs. Rin''ji hid something on island  there' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s在不经意间睡着了。' WHERE `entry` = -1000436 AND BINARY `content_default` = '%s suddenly falls asleep' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我们离开这里吧。我受够这些疯子了！' WHERE `entry` = -1000477 AND BINARY `content_default` = 'Let us leave this place. I''ve had enough of these madmen!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '蠢货，哪儿都别想去！' WHERE `entry` = -1000478 AND BINARY `content_default` = 'You''ll go nowhere, fool!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '小心！更多信徒来啦！' WHERE `entry` = -1000479 AND BINARY `content_default` = 'Beware! More cultists come!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '别想轻易逃跑！' WHERE `entry` = -1000480 AND BINARY `content_default` = 'You will not escape us so easily!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我能找到回去的路了。我的朋友米克达会好好奖励你的。' WHERE `entry` = -1000481 AND BINARY `content_default` = 'I can find my way from here. My friend Mekeda will reward you for your kind actions.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '不要让他们跑了！先杀掉那个强壮的家伙！' WHERE `entry` = -1000483 AND BINARY `content_default` = 'Don''t let them escape! Kill the strong one first!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '又过来了一些！小心！' WHERE `entry` = -1000484 AND BINARY `content_default` = 'More of them coming! Watch out!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '想跑？没门！消灭他们！' WHERE `entry` = -1000485 AND BINARY `content_default` = 'Where do you think you''re going? Kill them all!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '尝尝闪电的厉害，混蛋！' WHERE `entry` = -1000486 AND BINARY `content_default` = 'Ride the lightning, filth!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '冰霜震击！！！' WHERE `entry` = -1000487 AND BINARY `content_default` = 'FROST SHOCK!!!' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '最好我们现在就分开，以免他们派更多人来追击我们。希望我们之间有人可以成功回到加尔鲁什那里。保重，陌生人。' WHERE `entry` = -1000488 AND BINARY `content_default` = 'It is best that we split up now, in case they send more after us. Hopefully one of us will make it back to Garrosh. Farewell stranger.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '一个新来的家伙！记得等一会过来看看，我们总是希望能有更多人帮这些伤者一把。' WHERE `entry` = -1000490 AND BINARY `content_default` = 'A newcomer to Shattrath! Make sure to drop by later. We can always use a hand with the injured.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '注意你的言辞，卡德加的宠物正陪着这个人呢。' WHERE `entry` = -1000491 AND BINARY `content_default` = 'Be mindful of what you say, this one''s being shown around by Khadgar''s pet.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '愿圣光与你同在，$n。欢迎你来到沙塔斯。' WHERE `entry` = -1000493 AND BINARY `content_default` = 'Light be with you, $n. And welcome to Shattrath.' AND COALESCE(`content_loc4`, '') = '';
