UPDATE `script_texts` SET `content_loc4` = '卡德加亲自带你参观？你肯定给他留下了一个好印象，$n。' WHERE `entry` = -1000495 AND BINARY `content_default` = 'Khadgar himself is showing you around? You must have made a good impression, $n.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s抬起头，似乎在听着什么东西。' WHERE `entry` = -1000496 AND BINARY `content_default` = '%s lifts its head into the air, as if listening for something.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '%s发出的嚎叫在北边的山脉中回响，提醒你跟着它。' WHERE `entry` = -1000497 AND BINARY `content_default` = '%s lets out a howl that rings across the mountains to the north and motions for you to follow.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '好吧，听好了！在我周围排成圆圈，然后出发！' WHERE `entry` = -1000511 AND BINARY `content_default` = 'Aright, listen up! Form a circle around me and move out!' AND COALESCE(`content_loc4`, '') = '';
