UPDATE `script_texts` SET `content_loc4` = '我们不知道凡人是否一直都能进入时光之穴。说实话，这根本无从判断，因为时光之王始终在行动，随心所欲地改变着我们的时间流。你眼前的一切，明天很可能就不复存在。等你醒来，甚至可能完全不记得这个地方。' WHERE `entry` = -1000218 AND BINARY `content_default` = 'We do not know if the Caverns of Time have always been accessible to mortals. Truly, it is impossible to tell as the Timeless One is in perpetual motion, changing our timeways as he sees fit. What you see now may very well not exist tomorrow. You may wake up and have no memory of this place.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '这条时间流已经陷入了严重的混乱！我们的特工正在其中设法恢复秩序。据我掌握的情报，萨尔的自由正受到威胁。一个名叫永恒龙军团的邪恶组织正试图阻止他逃脱。我担心，如果没有外界的援助，一切都将无可挽回。' WHERE `entry` = -1000225 AND BINARY `content_default` = 'This timeway is in great disarray! We have agents inside right now attempting to restore order. What information I have indicates that Thrall''s freedom is in jeopardy. A malevolent organization known as the Infinite Dragonflight is trying to prevent his escape. I fear without outside assistance, all will be lost.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '这条时间流正在崩塌。它会给过去、现在和未来带来什么，目前还不得而知……' WHERE `entry` = -1000227 AND BINARY `content_default` = 'This timeway is currently collapsing. What that may hold for the past, present and future is currently unknown...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '我们的时间到了，$N。如果运气这种东西真的存在，我会祝你好运。' WHERE `entry` = -1000230 AND BINARY `content_default` = 'Our time is at an end $N. I would wish you luck, if such a thing existed.' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '纳鲁接纳了这些叛逃者，他们后来被称为占星者；他们居住在上方的平台上。只有加入占星者的人才获准进入那里。' WHERE `entry` = -1000247 AND BINARY `content_default` = 'The naaru accepted the defectors, who would become known as the Scryers; their dwelling lies in the platform above. Only those initiated with the Scryers are allowed there.' AND COALESCE(`content_loc4`, '') = '';
