UPDATE `script_texts` SET `content_loc4` = '一个阴暗而邪恶的存在侵入了翡翠梦境。它的力量随时可能蔓延到我们的世界，$N。我们必须阻止它！正因如此，我无法亲自陪你同行。' WHERE `entry` = -1000280 AND BINARY `content_default` = 'A shadowy, sinister presence has invaded the Emerald Dream. Its power is poised to spill over into our world, $N. We must oppose it! That''s why I cannot accompany you in person.' AND COALESCE(`content_loc4`, '') = '';
