UPDATE `script_texts` SET `content_loc4` = '我看没有哪一次比得上他说的那件事——他听说阿尔萨斯“表弟”的骨架被冻在冬泉谷的一座冰川下面。雷托尔，这件事我永远都不会原谅你。说真的……阿尔萨斯的表弟？' WHERE `entry` = -1000524 AND BINARY `content_default` = 'I don''t think it can top the one time where he told us that he''d heard that Artha''s "cousin''s" skeleton was frozen beneath a glacier in Winterspring. I''ll never forgive you for that one, Letoll. I mean honestly... Artha''s cousin?' AND COALESCE(`content_loc4`, '') = '';
