UPDATE `script_texts` SET `content_loc4` = '是的，伊利丹大人，我愿将这副雄伟的身躯献给您。今天你注定要倒下——成为托洛斯的又一个牺牲品……' WHERE `entry` = -1000534 AND BINARY `content_default` = 'Yes, Lord Illidan, I would sacrifice to you this magnificent physique. On this day you will fall - another victim of Torloth...' AND COALESCE(`content_loc4`, '') = '';
UPDATE `script_texts` SET `content_loc4` = '这么说，你们击败了火色魔印。现在又想挑战我的统治？连阿尔萨斯都无法打败我，你们竟敢有这样的念头？那么，来吧！来吧，$N！黑暗神殿在等着你们……' WHERE `entry` = -1000540 AND BINARY `content_default` = 'So you have defeated the Crimson Sigil. You now seek to challenge my rule? Not even Arthas could defeat me, yet you dare to even harbor such thoughts? Then I say to you, come! Come $N! The Black Temple awaits...' AND COALESCE(`content_loc4`, '') = '';
