UPDATE `script_texts` SET `content_loc4` = '上古之神的控制牢不可破。他已经被他们的邪恶思想彻底吞噬了……我……我……我不能……无法继续引导太久了……艾露恩，请帮助我。' WHERE `entry` = -1000693 AND BINARY `content_default` = 'The grasp of the Old Gods is unmoving. He is consumed by their dark thoughts... I... I... I cannot... cannot channel much longer... Elune aide me.' AND COALESCE(`content_loc4`, '') = '';
